@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* Figma 08 Pattern 3 (7275:15971): the header, the KPI row (16 apart, as Figma's KPI rows are), then
   the orders card with its toolbar, the table full-bleed and the footer. The drawer's contents are
   the order's lines and a short list of facts. The KPI row follows the page's own width. */
@layer nz.patterns {
  .nzp-orders-page {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-6);
    min-inline-size: 0;
    container-type: inline-size;
  }

  .nzp-orders-page-kpis {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--nz-space-4);
  }

  @container (width >= 30rem) {
    .nzp-orders-page-kpis {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @container (width >= 56rem) {
    .nzp-orders-page-kpis {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }
  }

  /* the parts pad themselves, so the table can run to the card's edges */
  .nzp-orders-page-card {
    gap: 0;
    padding: 0;
    overflow: hidden;
  }

  .nzp-orders-page-toolbar {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-4);
    padding: var(--nz-space-4) var(--nz-space-6);
  }

  .nzp-orders-page-search {
    max-inline-size: 30rem;
  }

  /* the card draws the edge: the table loses its own side borders and radius */
  .nzp-orders-page-table {
    border-inline-width: 0;
    border-radius: 0;
  }

  .nzp-orders-page-customer {
    display: inline-flex;
    align-items: center;
    gap: var(--nz-space-2);
  }

  .nzp-orders-page-pagination {
    padding: var(--nz-space-4) var(--nz-space-6);
  }

  .nzp-orders-page-lines {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-3);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .nzp-orders-page-line {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto auto;
    align-items: center;
    gap: var(--nz-space-3);
  }

  .nzp-orders-page-thumb {
    inline-size: 2.5rem;
    block-size: 2.5rem;
    border-radius: var(--nz-radius-sm);
    background: var(--nz-bg-muted);
  }

  .nzp-orders-page-facts {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-3);
    margin: 0;
  }

  .nzp-orders-page-facts > div {
    display: grid;
    grid-template-columns: 5rem minmax(0, 1fr);
    gap: var(--nz-space-3);
  }

  .nzp-orders-page-facts dd {
    margin: 0;
  }
}
